use sim_editor_ui::{*,projection::{RuntimeUiState,UiRole},language::{CatalogRegistry,LocaleId},intents::*,transport::{InputTransport,InputOwner}};
use sim_model::{Document,DecodeLimits,ParameterId,Value,ValueId,TimeTicks};
use sim_runtime::{Session,SessionConfig,CommandKind};
use sim_render::input::InputCoordinator;
struct Owner(InputCoordinator);
impl InputOwner for Owner{
 fn begin(&mut self,s:&Session,_:UiRole,k:&[ParameterId])->Result<(),String>{self.0.begin(s,k).map_err(|e|e.to_string())}
 fn update(&mut self,s:&mut Session,e:Vec<(ParameterId,Option<Value>)>)->Result<bool,String>{self.0.update(s,e).map_err(|e|e.to_string())}
 fn commit(&mut self,s:&mut Session)->Result<bool,String>{self.0.commit(s).map_err(|e|e.to_string())}
 fn cancel(&mut self,s:&mut Session)->Result<bool,String>{self.0.cancel(s).map_err(|e|e.to_string())}
 fn abandon(&mut self,s:&Session){self.0.abandon(s);}
}
fn project<'a>(s:&'a Session,f:&'a sim_runtime::FrameSnapshot,o:&Owner)->EditorProjection<'a>{EditorProjection::from_runtime(f,s.document().document(),RuntimeUiState{role:UiRole::Reader,playing:s.is_playing(),playback_intent:s.playback_intent(),can_undo:o.0.can_undo(),can_redo:o.0.can_redo()}).unwrap()}
fn key(k:egui::Key,m:egui::Modifiers)->egui::Event{egui::Event::Key{key:k,physical_key:Some(k),pressed:true,repeat:false,modifiers:m}}
struct Lab{s:Session,o:Owner,b:InputTransport,ui:EditorUi,ctx:egui::Context,c:CatalogRegistry,time:f64,controls:Vec<sim_editor_ui::accessibility::SemanticControl>,results:Vec<(GesturePhase,Result<bool,String>,bool)>}
impl Lab{
 fn new()->Self{let mut x=Self{s:Session::new(Document::decode(include_bytes!("../../../fixtures/render/cosines-runtime.json"),DecodeLimits::default()).unwrap(),sim_math::OperatorRegistry::standard().unwrap(),SessionConfig::default()).unwrap(),o:Owner(Default::default()),b:Default::default(),ui:Default::default(),ctx:Default::default(),c:Default::default(),time:0.,controls:vec![],results:vec![]};for _ in 0..3{x.frame(vec![]);}x}
 fn frame(&mut self,events:Vec<egui::Event>){
  self.time+=0.02;let f=self.s.snapshot();let p=project(&self.s,&f,&self.o);let mut output=UiOutput::default();
  let mut full=self.ctx.run_ui(egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(1000.,700.))),time:Some(self.time),events,..Default::default()},|root|{egui::CentralPanel::default().show(root,|ui|{self.ui.draw_panel(ui,Panel::Inspector,&p,&Default::default(),self.c.language(&self.ui.view.locale).unwrap(),&mut output);});self.ui.inspector.retire_focus(root.ctx(),&p,&mut output);});
  full.textures_delta.clear();self.controls=output.semantics;
  eprintln!("TRACE focus={:?} ui={:?}",self.ctx.memory(|m|m.focused()),self.ui.inspector.drafts.iter().map(|(k,d)|(k.as_str(),&d.text,d.dirty,d.pending,&d.error)).collect::<Vec<_>>());
  let gestures=output.intents.into_iter().filter_map(|i|if let UiIntent::Gesture(g)=i{Some(g)}else{None}).collect();
  let feedback=self.b.handle_frame(&mut self.s,&mut self.o,gestures).unwrap();
  let f=self.s.snapshot();let p=project(&self.s,&f,&self.o);let l=self.c.language(&self.ui.view.locale).unwrap();
  self.results.clear();for item in feedback{self.results.push((item.event.phase,item.result.clone(),self.s.is_playing()));self.ui.inspector.acknowledge(&item,Some(&p),l);}
 }
 fn focus(&mut self,id:&str){let pos=self.controls.iter().find(|x|x.id==format!("parameter:{id}")).unwrap().rect.center();self.frame(vec![egui::Event::PointerMoved(pos),egui::Event::PointerButton{pos,button:egui::PointerButton::Primary,pressed:true,modifiers:Default::default()}]);self.frame(vec![egui::Event::PointerButton{pos,button:egui::PointerButton::Primary,pressed:false,modifiers:Default::default()}]);}
 fn replace(&mut self,text:&str){self.press(egui::Key::A,egui::Modifiers::COMMAND);self.frame(vec![egui::Event::Text(text.into())]);}
 fn press(&mut self,k:egui::Key,m:egui::Modifiers){self.frame(vec![key(k,m)]);self.frame(vec![egui::Event::Key{key:k,physical_key:Some(k),pressed:false,repeat:false,modifiers:m}]);}
 fn enter(&mut self){self.press(egui::Key::Enter,Default::default());}
 fn scalar(&self,id:&str)->f64{self.s.snapshot().truth()[&ValueId::new(id).unwrap()].as_scalar().unwrap()}
 fn draft(&self,id:&str)->&sim_editor_ui::panels::inspector::Draft{&self.ui.inspector.drafts[&ParameterId::new(id).unwrap()]}
 fn set(&mut self,id:&str,x:f64){self.s.dispatch(self.s.snapshot().command(CommandKind::SetLiveOverride{parameter:ParameterId::new(id).unwrap(),value:Value::scalar(x).unwrap()})).unwrap();}
}
#[test]fn clean_focus_transfer_both_widget_orders_and_noop_enter(){for(a,b)in[("theta","b"),("b","theta")]{let mut x=Lab::new();x.focus(a);x.focus(b);assert!(x.b.active());x.replace(if b=="b"{"5"}else{"1.25"});x.enter();assert_eq!(x.scalar(b),if b=="b"{5.}else{1.25});assert!(!x.draft(b).dirty);assert!(!x.b.active());assert!(!x.o.0.active());}let mut x=Lab::new();let revision=x.s.revision();x.focus("theta");x.enter();assert!(!x.b.active());assert_eq!(x.s.revision(),revision);assert!(x.s.live_overrides().is_empty());}
#[test]fn dirty_transfer_commits_old_before_new_begin_in_both_orders(){for(a,b)in[("theta","b"),("b","theta")]{let mut x=Lab::new();x.focus(a);x.replace(if a=="b"{"5"}else{"1.25"});x.focus(b);assert_eq!(x.scalar(a),if a=="b"{5.}else{1.25});assert!(!x.draft(a).dirty);x.replace(if b=="b"{"6"}else{"1.5"});x.enter();assert_eq!(x.scalar(b),if b=="b"{6.}else{1.5});assert!(!x.draft(b).dirty);}}
#[test]fn rejected_range_stays_dirty_and_can_retry(){let mut x=Lab::new();x.focus("a");x.replace("-1");x.enter();assert_eq!(x.scalar("a"),3.);assert!(x.draft("a").dirty);assert_eq!(x.draft("a").error.as_deref(),Some("draft.invalid"));assert_eq!(x.s.revision(),0);x.replace("4");x.enter();assert_eq!(x.scalar("a"),4.);assert!(!x.draft("a").dirty);}
#[test]fn dirty_touched_aba_rejects_and_escape_releases(){let mut x=Lab::new();x.focus("a");x.replace("4");x.set("a",6.);x.set("a",3.);let rev=x.s.revision();x.enter();assert_eq!(x.scalar("a"),3.);assert_eq!(x.s.revision(),rev);assert!(x.draft("a").dirty);assert_eq!(x.draft("a").error.as_deref(),Some("draft.stale"));assert!(!x.b.active());x.frame(vec![key(egui::Key::Escape,Default::default())]);assert!(!x.draft("a").dirty);x.focus("b");x.replace("5");x.enter();assert_eq!(x.scalar("b"),5.);}
#[test]fn same_field_refocus_and_multiple_enter_cycles(){let mut x=Lab::new();for n in[4.,5.,6.]{x.focus("a");x.replace(&n.to_string());x.enter();assert_eq!(x.scalar("a"),n);assert!(!x.draft("a").dirty);assert!(!x.b.active());}x.o.0.undo(&mut x.s).unwrap();assert_eq!(x.scalar("a"),5.);x.o.0.redo(&mut x.s).unwrap();assert_eq!(x.scalar("a"),6.);}
#[test]fn clean_locale_reformats_but_dirty_keeps_edit_decimal(){let mut x=Lab::new();x.ui.view.locale=LocaleId::new("ru").unwrap();x.frame(vec![]);assert!(x.draft("theta").text.contains(','));let revision=x.s.revision();x.ui.view.locale=LocaleId::new("en").unwrap();x.frame(vec![]);assert!(!x.draft("theta").text.contains(','));assert_eq!(x.s.revision(),revision);x.ui.view.locale=LocaleId::new("ru").unwrap();x.focus("theta");x.replace("1,25");x.ui.view.locale=LocaleId::new("en").unwrap();x.frame(vec![]);assert_eq!(x.draft("theta").text,"1,25");x.enter();assert_eq!(x.scalar("theta"),1.25);assert_eq!(x.draft("theta").text,"1.25");}
#[test]fn play_invalid_pending_then_current_time_valid_and_clean_noop(){let mut x=Lab::new();x.s.set_playing(x.s.revision(),true).unwrap();x.focus("a");x.replace("-1");x.enter();assert!(x.s.is_playing());x.s.seek(x.s.revision(),TimeTicks::new(1000)).unwrap();x.replace("4");x.enter();assert_eq!(x.scalar("a"),4.);assert_eq!(x.s.snapshot().time(),TimeTicks::new(1000));assert!(x.s.playback_intent());assert!(x.s.is_playing());x.o.0.undo(&mut x.s).unwrap();assert!(!x.s.live_overrides().contains_key(&ParameterId::new("a").unwrap()));}
#[test]fn redo_specific_chord_and_text_focus_routing(){let mut x=Lab::new();x.focus("a");x.replace("4");x.enter();x.o.0.undo(&mut x.s).unwrap();let f=x.s.snapshot();let p=project(&x.s,&f,&x.o);let ctx=egui::Context::default();let mut out=UiOutput::default();let mut full=ctx.run_ui(egui::RawInput{events:vec![key(egui::Key::Z,egui::Modifiers::COMMAND|egui::Modifiers::SHIFT)],..Default::default()},|root|sim_editor_ui::hotkeys::gather(root.ctx(),&p,&mut out));full.textures_delta.clear();assert!(matches!(out.intents.as_slice(),[UiIntent::View(ViewIntent::UndoInput{redo:true})]));x.o.0.redo(&mut x.s).unwrap();assert_eq!(x.scalar("a"),4.);
 let mut out=UiOutput::default();let f=x.s.snapshot();let p=project(&x.s,&f,&x.o);let mut full=x.ctx.run_ui(egui::RawInput{events:vec![key(egui::Key::Z,egui::Modifiers::COMMAND)],..Default::default()},|root|sim_editor_ui::hotkeys::gather(root.ctx(),&p,&mut out));full.textures_delta.clear();assert!(out.intents.is_empty());
}
#[test]fn foreign_gesture_cannot_terminate_current_owner_and_blur_is_nonwriting(){let mut x=Lab::new();x.focus("a");let current=x.b.active_gesture().unwrap();let e=GestureIntent{role:UiRole::Reader,source:InputSource::Keyboard,stamp:sim_editor_ui::projection::ProjectionStamp::capture(&x.s.snapshot()),gesture:current.wrapping_add(1),pointer:2,phase:GesturePhase::Cancelled,entries:vec![]};assert!(x.b.handle(&mut x.s,&mut x.o,&e).is_err());assert!(x.b.active());let rev=x.s.revision();x.b.cancel(&mut x.s,&mut x.o).unwrap();assert_eq!(x.s.revision(),rev);assert!(!x.b.active());}
#[test]fn single_input_pass_feedback_publishes_on_following_frame(){let mut x=Lab::new();x.focus("a");x.replace("4");x.enter();let revision=x.s.revision();x.frame(vec![]);assert_eq!(x.s.revision(),revision);assert!(x.results.is_empty());assert!(!x.b.active());assert_eq!(x.draft("a").text,"4");assert_eq!(x.scalar("a"),4.);}
